פתרון ראשון:
```c
int FindDouble(int* a ,  int n)
{
    int low = 0, high = n - 1, mid;
    while (low < high)
    {
        mid = (high-low)/2+low;
        if (a[mid] == a[mid + 1])
            return a[mid];

        if(a[mid] - a[low] == mid - low)

            low = mid + 1;
        else
            high = mid;
    }
}
```
פתרון שני:
```c
int findDoubleNum(int *a, int n)
{
    int low = 0, high = n - 1, mid;
    /*if (n == 2)
        return a[0];*/

    while (low <= high)
    {
        mid = (high - low) / 2 + low;
        if (a[mid] == a[0]+mid)
            low = mid + 1;
        else
            high = mid-1;
    }
    return a[mid];
}
```

